import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"蠱","description":"周易集解 - 蠱","frontmatter":{"title":"蠱","description":"周易集解 - 蠱"},"headers":[],"relativePath":"classics/jijie/018.md","filePath":"classics/jijie/018.md"}'),l={name:"classics/jijie/018.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="蠱" tabindex="-1">蠱 <a class="header-anchor" href="#蠱" aria-label="Permalink to “蠱”">​</a></h1><h2 id="蠱-1" tabindex="-1">蠱 <a class="header-anchor" href="#蠱-1" aria-label="Permalink to “蠱”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>蠱，元亨。利涉大川。先甲三日，後甲三日。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：以喜隨人者必有事，故受之以蠱。蠱者，事也。</p><p>《九家易》曰：子行父事，備物致用，而天下治也。備物致用，立成器以為天下利，莫大於聖人。子修聖道，行父之事，以臨天下，無為而治也。</p><p>虞翻曰：泰初之上，與隨旁通。剛上柔下，乾坤交，故元亨也。</p><p>伏曼容曰：蠱，惑亂也。萬事從惑而起，故以蠱為事也。</p><p>案：《尚書大傳》雲：乃命五史，以書五帝之蠱事。然為訓者，正以太古之時無為無事也。今言蠱者，是卦之惑亂也。時既漸澆，物情惑亂，故事業因之而起惑矣。故《左傳》雲：女惑男，風落山，謂之蠱，是其義也。</p><p>虞翻曰：謂二失位，動而之坎也，故利涉大川也。</p><p>《子夏傳》雲：先甲三日者，辛、壬、癸也。後甲三日者，乙、丙、丁也。</p><p>馬融曰：甲在東方，艮在東北，故雲先甲。巽在東南，故雲後甲。所以十日之中唯稱甲者。甲為十日之首，蠱為造事之端，故舉初而明事始也。言所以三日者，不令而誅謂之暴，故令先後各三日，欲使百姓遍習，行而不犯也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：蠱，剛上而柔下，巽而止，蠱。蠱，元亨，而天下治也。利涉大川，往有事也。先甲三日，後甲三日，終則有始，天行也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>虞翻曰：泰初之上，故剛上；坤上之初，故柔下。上艮下巽，故巽而止，蠱也。</p><p>荀爽曰：蠱者，巽也。巽歸合震，故元亨也。蠱者，事也。備物致用，故天下治也。</p><p>《九家易》曰：陽往據陰，陰來承陽，故｢有事也｣。此卦泰乾天有河，坤地有水，二爻升降，出入乾坤，利涉大川也。陽往求五，陰來求二，未得正位，戎事不息，故有事。</p><p>虞翻曰：謂初變成乾，乾為甲。至二成離，離為日。謂乾三爻在前，故｢先甲三日｣。賁，時也。變三至四，體離。至五成乾，乾三爻在後，故｢後甲三日｣。無妄，時也。易出震，消息歷乾坤象。乾為始，坤為終，故終則有始。乾為天。震為行，故天行也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：山下有風，蠱。君子以振民育德。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>何妥曰：山者高而靜，風者宣而疾，有似君處上而安靜，臣在下而行令也。</p><p>虞翻曰：君子，謂泰乾也。坤為民。初上撫坤，故振民。乾稱德，體大畜，須養，故以育德也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，乾父之蠱，有子考，無咎。厲，終吉。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：乾，正。蠱，事也。泰乾為父，坤為事。故乾父之蠱。初上易位，艮為子，父死大過稱考，故有子考。變而得正，故｢無咎。厲，終吉｣也。</p><p>案：位陽令首，父之事也；爻陰柔順，子之質也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：乾父之蠱，意承考也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：幹事之首，時有損益，不可盡承，故意承而已也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，乾母之蠱，不可貞。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：乾母之蠱，得中道也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：應在五。泰坤為母，故乾母之蠱。失位。故不可貞。變而得正，故貞而得中道也。</p><p>案：位陰居內，母之象也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，乾父之蠱，小有悔，無大咎。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：乾父之蠱，終無咎也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：以剛幹事，而無其應，故有悔也。履得其位，以正乾父，雖小有悔，終無大咎矣。</p><p>案：爻位俱陽，父之事。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，裕父之蠱，往見吝。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：裕，不能爭也。孔子曰：父有爭子，則身不陷於不義。四陰體大過，本末弱，故裕父之蠱。兌為見，變而失正，故往見吝。《象》曰｢往未得｣。是其義也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：裕父之蠱，往未得也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：往失位，折鼎足，故未得。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，乾父之蠱，用譽。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>荀爽曰：體和應中，承陽有實，用斯幹事，榮譽之道也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：乾父用譽，承以德也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：譽，謂二也。二五失位，變而得正，故用譽。變二使承五，故承以德。二乾爻，故稱德矣。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，不事王侯，高尚其事。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：泰乾為王，坤為事。應在於三。震為侯，坤象不見，故不事王侯。</p><p>虞翻曰：謂五已變，巽為高，艮陽升在坤上，故高尚其事。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：不事王侯，志可則也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：年老事終，不當其位。體艮為止。故不事王侯。據上臨下，重陰累實，故志可則。</p>',73)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
